function ARHelper.tryInit()
	if self._initCalled then
		return
	end

	self._initCalled = true

	if DeviceHelper.IsLowMemoryDevice then
		return
	end

	local key
	local packageName = UnityEngine.Application.identifier

	if DeviceHelper.isIOS() then
		key = self.OVERRIDE_IOS[packageName]
	else
		key = self.OVERRIDE_ANDROID[packageName]
	end

	if key == nil then
		key = self.KEY_MAIN
	end

	ARUtils.InitLicense(key)
end

function ARHelper.tryOpenARDlg(heroId, isMainMenu, heroList)
	if GameConfig.getChannelConfig(Const.REMOTE_CONFIG_HIDE_AR_DLG) == 1 then
		MsgManager.notice(Lang.get(1836))

		return
	end

	ARHelper.tryInit()

	if not self._checkPermission() then
		return
	end

	if ARUtils.IsInitialized() and not NativeHelper.isEmulator() then
		local allowed = true

		if allowed then
			if isMainMenu and heroList then
				local arDlg = UIManager.getUI("mainMenuArDlg", true)

				arDlg:directShowMainmenuHeros(heroList)
			elseif heroId then
				local arDlg = UIManager.getUI("arDlg", true)

				arDlg:directShowSingleHero(heroId)
			end
		else
			MsgManager.notice(Lang.get(29947))
		end
	else
		MsgManager.notice(Lang.get(29948))
	end
end

function ARHelper._checkPermission()
	local granted = NativeHelper.checkCameraPermission()

	if not granted then
		MsgManager.notice(Lang.get(29949))
	end

	return granted
end

return ARHelper
